from author_library import *
cards=[]
cards.append(compact('wu_father','伍路元之父','伍路元的父亲没有具名，是《非常遭遇》旧事中把家庭贫困推向暴力的明确行动者。他沉迷赌博，把儿子捡废纸换来的买米钱拿到赌局上，妻子生病、家中没有食物也不能使他停手。少年循线去找他，所求只是让父亲归还家庭赖以吃饭的钱，却听到他拿妻子去抵债的叫喊。伍路元忍不住出言抗议，他便用一记重掌回应，五道红印留在儿子脸上，少年冲到街上后遭车撞断右腿。之后的故事使这场伤害意外与陈老的梦相连，成为另一种人生的开端，但那不能倒过来证明父亲的暴力是应当感谢的命运安排。他没有证实的预知、赌术或特殊力量，也不知自己的行为会触发怎样的后果。终局未再交代其个人下落，卡片只保留这位自利而失控的家庭施暴者最后已知人身。新场景中不必机械复演伤害，行为冲突可以从逃避责任、索取钱财、把亲人视为可支配物的习惯展开；他是否停止，需要面对真实后果，而不是用所谓救星结局给暴力免责。','《非常遭遇》历史线打伤儿子后未再交代下落，最后可确认是普通成年男子','反派','继续赌博并逃避家庭负担，以亲人的付出供养自己的欲望','把索取当作理所当然，不愿认真处理家人的饥饿和病痛','赌局被打断或被儿子质问时以羞辱和暴力压制对方','他应承担所做选择的后果，不能借后来偶然的好结果推卸责任',[ab('普通成年人的近身暴力','曾一掌把儿子打出清晰掌印','没有专业武术或超常力量证据；对弱者施暴不等于强大战斗力')],[ev('141',110,126,'贫困、赌米钱和抵妻叫喊'),ev('141',126,140,'掌击与儿子冲上街头')],profile='ordinary'))
cards.append(compact('wu_corrupt_official','第三场梦牵涉的大贪官','这名未具名的高官是伍路元第三次所谓梦中遭遇的关键筹码。他曾积累惊人的非法财富，事发被捕后面临公众期待中的严厉惩罚。王莲和伍家部长孙子的计划把他的命运包装成一个可以由伍路元选择改变的结果：只要接受资源合作，便能让他“立功”，同时拯救伍家的未来。这套说辞利用了长者相信梦与救星的心理，也借政治案件的巨大声势给骗局制造重量。但王莲后来的说明使边界很明确，高官免死本来已经是中央决定，所谓借此将功赎罪只是内部说明，并不是伍路元真的通过梦控制了审判。高官本人没有展示托梦、预知或操纵命运的能力，也没有证明他亲自策划了每一步说辞。卡片以已经被捕但免死的腐败官员为终局，不给他原官位和百亿资金的随身调用权。可演绎的核心是凭制度关系和利益交换谋求生路、对公众后果的疏离，以及失去安全感后如何面对真实责任；他不能因为成为别人骗局中的棋子就被洗成无辜人物。','《非常遭遇》被捕后获免死处理，具体刑期未交代，原官权不可自动保留','反派','保住生命与可回旋的空间，逃避腐败行为带来的清算','习惯在权力和利益关系中寻找保障','面临惩罚时寻求能改变处置的关系，却不能保证自身仍掌握主动','免死的现实决定与围绕此事的诈骗说辞必须区分',[ab('历史官僚关系经验','熟悉权力与财富的交换方式','终局在押，原职权和赃款不作为随身资源；未证实主动超常能力')],[ev('141',1215,1279,'腐败案件被包装成合作筹码'),ev('141',1288,1292,'免死结果及中央原定决定')],profile='ordinary',aliases=['大贪官']))
cards.append(compact('blue_visitors','岩石遭遇的蓝色外星人','这组蓝色外星人存在于岩石久远的特殊经历以及长老保存的消息中，不能把他们与后来接收的蓝色美人图像简单合并。岩石同他们生活，因身材条件参与建设，却并不掌握他们的科学体系；当双方关系发生变化，他被排除在原有生活之外，带着无法归返的渴望在地球继续漫长岁月。长老后来确认，确有外星人向他说明岩石的来历，因而这个过去具有比单纯幻想更强的依据。但卫斯理等人由图像、信号及尺度推导出文明不断缩小、已小于尘埃的解释，仍是推测，没有亲自进入并验证，也没有证实所有蓝色人现在同处一个可用的空间。终局卡以这个能够作出集体决定、曾把岩石送离的文明群体记录其阶段性对立作用；不从未知科技直接推导宇宙级攻击，更不写成每个成员都能随意缩小一切。若作为角色参与，只能通过已知交流关系和有条件的接触呈现，未知生活尺度、具体设备、成员姓名和政治结构继续留空。共同条目只用于无法区分的集体行动，不能替未露面的每一个人发明相同性格。','《一个地方》《须弥芥子》所述历史蓝色外星群体，当前居所与尺度未获证实','阶段性对立者','维持自身生活秩序，并决定与外来者之间的关系边界','在已有接触关系中传递有限消息，不主动解释所有科技细节','外来者不再适合其安排时可以中止接纳，造成长期分离','成员行动只按已记述的事实表现，观察者的微缩猜想不等于群体已公开的能力',[ab('外星文明技术与交流','曾与岩石共同生活并处理其离开，另与长老建立过信息联系','具体设备和可控范围不明；微缩文明及护罩机制未被证实')],[ev('143',1299,1306,'长老确认外星消息及微缩仅属推论'),ev('143',1320,1328,'防护与图像身份仍属设想')],profile='ordinary',extra={'baseline':{'destruction':'没有可量化的直接攻击展示，未知科技不直接折算为破坏力。','durability':'蓝色外星人的生理与抗性没有足够证据，不能套用不死、金刚或免疫。','speed':'未确定其个人移动速度；文明交通不计每个成员肉身速度。','energy':'可能具有先进设备，但未列明可供本条目独立调用的攻击装置。','stamina':'生理和设备续航未明，不设置无限持续。'},'confidence':'low','uncertainties':['微缩文明解释未被证实；不能确认蓝色美人图像是活体成员的直接直播。','历史集体决定没有分别具名的行动者，暂以群体条目保存。']}))
save(cards)
